mapper.update:
UPDATE emp54_errand
   SET emp54_errand_cd    = #{req.errandCode}
     , emp54_date         = #{req.date}
     , emp54_depart_time  = #{req.departTime}
     , emp54_return_time  = #{req.returnTime}
     , emp54_reason       = #{req.reason}
     , emp54_venue        = #{req.venue}
     , emp54_host         = #{req.host}
     , emp54_note         = #{req.note}
     , emp54_public_yn    = CAST(#{req.publicYn} AS VARCHAR)
 WHERE emp54_errand_id = #{req.errandId}
   AND emp54_company_id = #{companyId}
   AND emp54_person_id = #{personId}

